tasks.solution:
-- 이 질의를 고쳐 같은 행의 id와 name을 함께 보이세요.
-- 한 행은 한 물건이에요. 같은 행의 열끼리 그 물건의 정보예요.
SELECT id, name FROM items ORDER BY id;

