-- ID는 물건을 구별하고 이름은 겹칠 수 있어요.
CREATE TABLE items(id INTEGER PRIMARY KEY, name TEXT NOT NULL, stock INTEGER CHECK(stock>=0));
INSERT INTO items VALUES(1,'pen',2),(2,'pen',3),(3,'book',NULL);
CREATE TABLE lots(item_id INTEGER REFERENCES items(id), batch INTEGER, PRIMARY KEY(item_id,batch));
INSERT INTO lots VALUES(1,1),(1,2),(2,1);

