-- ID는 물건을 구별하고 이름은 겹칠 수 있어요.
CREATE TABLE items(id INTEGER PRIMARY KEY, name TEXT NOT NULL, stock INTEGER CHECK(stock>=0));
INSERT INTO items VALUES(2,'bag',5),(3,'box',6);
CREATE TABLE lots(item_id INTEGER REFERENCES items(id), batch INTEGER, PRIMARY KEY(item_id,batch));
INSERT INTO lots VALUES(3,1),(3,2),(2,9);

tasks.solution:
-- 이 질의에 열을 더해 이름 종류 수 옆에 ID 종류 수도 보이세요.
-- 이름은 겹칠 수 있지만 ID는 물건마다 달라 물건 수와 같아요.
SELECT COUNT(DISTINCT name) AS names, COUNT(DISTINCT id) AS ids FROM items;

