tasks.solution:
-- 이 질의에 JOIN을 더해 로트마다 물건 이름을 보이세요.
-- lots.item_id는 items.id를 가리키는 번호예요. 같은 번호의 items 행과 이어 이름을 읽어요.
SELECT lots.item_id, lots.batch, items.name FROM lots JOIN items ON lots.item_id = items.id ORDER BY lots.item_id, lots.batch;

